package com.xiaoxiaoshuo.reader;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.JSONObject;import java.util.*;
public class BookDetailActivity extends Activity{
 private final int green=Color.rgb(49,88,71);private LinearLayout catalogBox;private TextView status,titleView,authorView,introView;private ImageView coverView;private LegacyDexBridge.BookResult book=new LegacyDexBridge.BookResult();private ArrayList<LegacyDexBridge.Chapter> chapters=new ArrayList<>();private int shown=0;private String catalogKey="";
 @Override public void onCreate(Bundle b){super.onCreate(b);readIntent();build();resolveAndCatalog();}
 private void readIntent(){Intent i=getIntent();book.title=n(i,"title");book.author=n(i,"author");book.intro=n(i,"intro");book.coverUrl=n(i,"cover");book.bookUrl=n(i,"book_url");book.sourceName=n(i,"source_name");book.sourceUrl=n(i,"source_url");book.sourceJson=n(i,"source_json");}private String n(Intent i,String k){String s=i.getStringExtra(k);return s==null?"":s;}
 private void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(247,244,238));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(dp(12),dp(8),dp(12),dp(6));TextView back=tx("‹",32,green,true);back.setGravity(Gravity.CENTER);back.setOnClickListener(v->finish());top.addView(back,new LinearLayout.LayoutParams(dp(48),dp(50)));TextView topTitle=tx("书籍详情",17,Color.rgb(44,53,48),true);topTitle.setGravity(Gravity.CENTER_VERTICAL);top.addView(topTitle,new LinearLayout.LayoutParams(0,dp(50),1));root.addView(top);ScrollView sv=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),dp(12),dp(20),dp(36));LinearLayout hero=card();hero.setOrientation(LinearLayout.HORIZONTAL);coverView=new ImageView(this);coverView.setImageDrawable(new LiteraryCoverDrawable(book.title));hero.addView(coverView,new LinearLayout.LayoutParams(dp(112),dp(158)));LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.setPadding(dp(16),dp(4),0,0);titleView=tx(book.title.length()>0?book.title:"未命名书籍",23,Color.rgb(39,49,44),true);info.addView(titleView);authorView=tx(book.author.length()>0?book.author:"作者待获取",14,Color.rgb(116,108,97),false);authorView.setPadding(0,dp(7),0,dp(9));info.addView(authorView);info.addView(tx(book.sourceName.length()>0?"来源 · "+book.sourceName:"正在匹配优质书源",12,green,true));hero.addView(info,new LinearLayout.LayoutParams(0,dp(158),1));box.addView(hero,mp(0,0,0,14));CoverLoader.load(coverView,book.coverUrl,book.bookUrl.length()>0?book.bookUrl:book.sourceUrl,book.sourceJson,book.title);introView=tx(book.intro.length()>0?book.intro:"正在获取完整简介…",14,Color.rgb(77,75,70),false);introView.setLineSpacing(dp(4),1f);LinearLayout intro=card();intro.addView(introView);box.addView(intro,mp(0,0,0,14));LinearLayout actions=new LinearLayout(this);Button shelf=btn("＋ 加入书架");shelf.setOnClickListener(v->addShelf());Button read=btn("开始阅读");read.setOnClickListener(v->{if(chapters.isEmpty())Toast.makeText(this,"目录还没有加载完成",Toast.LENGTH_SHORT).show();else openChapter(0);});actions.addView(shelf,new LinearLayout.LayoutParams(0,dp(50),1));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(0,dp(50),1);rp.leftMargin=dp(10);actions.addView(read,rp);box.addView(actions,mp(0,0,0,20));LinearLayout titleRow=new LinearLayout(this);titleRow.setGravity(Gravity.CENTER_VERTICAL);titleRow.addView(tx("章节目录",20,Color.rgb(43,58,50),true),new LinearLayout.LayoutParams(0,-2,1));status=tx("正在查找目录…",12,Color.rgb(130,122,110),false);status.setGravity(Gravity.CENTER_VERTICAL);titleRow.addView(status);box.addView(titleRow,mp(0,0,0,10));catalogBox=new LinearLayout(this);catalogBox.setOrientation(LinearLayout.VERTICAL);box.addView(catalogBox);sv.addView(box);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);getWindow().setStatusBarColor(Color.rgb(247,244,238));getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);}
 private void resolveAndCatalog(){new Thread(()->{try{if(book.sourceJson.length()==0||book.bookUrl.length()==0){LegacyDexBridge.BookResult found=findBook(book.title);if(found!=null)book=found;}if(book.sourceJson.length()==0)throw new Exception("NO_SOURCE");try{LegacyDexBridge.BookResult d=LegacyDexBridge.get(this).loadDetail(book);if(d!=null){d.sourceJson=book.sourceJson;if(d.sourceName.length()==0)d.sourceName=book.sourceName;if(d.sourceUrl.length()==0)d.sourceUrl=book.sourceUrl;book=d;}}catch(Throwable ignored){}chapters=new ArrayList<>(LegacyDexBridge.get(this).loadCatalog(book));if(chapters.isEmpty()){LegacyDexBridge.BookResult alt=findBookExcluding(book.title,book.sourceUrl);if(alt!=null){ArrayList<LegacyDexBridge.Chapter> ac=new ArrayList<>(LegacyDexBridge.get(this).loadCatalog(alt));if(!ac.isEmpty()){book=alt;chapters=ac;}}}catalogKey=CatalogStore.save(this,book.title,book.sourceJson,chapters);runOnUiThread(this::renderResolved);}catch(Throwable e){runOnUiThread(()->{status.setText("优选书源均暂未获取到目录");catalogBox.removeAllViews();TextView tip=tx("可以稍后重试，应用会自动更新书源并移除连续失效的来源。",14,Color.rgb(105,98,88),false);tip.setPadding(dp(14),dp(18),dp(14),dp(18));catalogBox.addView(tip);});}}).start();}
 private LegacyDexBridge.BookResult findBook(String q){return findBookExcluding(q,"");}private LegacyDexBridge.BookResult findBookExcluding(String q,String exclude){LegacySourceStore.State st=LegacySourceStore.prepare(this,80);LegacyDexBridge.BookResult fallback=null;for(LegacySourceStore.SourceInfo s:st.selected){if(s.url.equals(exclude))continue;try{List<LegacyDexBridge.BookResult> list=LegacyDexBridge.get(this).search(s,q,1);for(LegacyDexBridge.BookResult b:list){if(fallback==null)fallback=b;if(norm(b.title).equals(norm(q)))return b;}}catch(Throwable ignored){}}return fallback;}private String norm(String s){return s==null?"":s.replace(" ","").replace("《","").replace("》","").toLowerCase(Locale.ROOT);}
 private void renderResolved(){titleView.setText(book.title);authorView.setText(book.author.length()>0?book.author:"作者未知");introView.setText(book.intro.length()>0?AiTypesetter.compactIntro(book.intro):"暂无简介");CoverLoader.load(coverView,book.coverUrl,book.bookUrl.length()>0?book.bookUrl:book.sourceUrl,book.sourceJson,book.title);status.setText(chapters.isEmpty()?"未获取到目录":"共 "+chapters.size()+" 章");catalogBox.removeAllViews();shown=0;showMore();}
 private void showMore(){int end=Math.min(chapters.size(),shown+80);for(int i=shown;i<end;i++){final int idx=i;LegacyDexBridge.Chapter ch=chapters.get(i);TextView row=tx((i+1)+"  "+ch.name,15,Color.rgb(61,66,62),false);row.setPadding(dp(12),dp(14),dp(12),dp(14));row.setBackgroundColor(i%2==0?Color.WHITE:Color.rgb(251,249,244));row.setOnClickListener(v->openChapter(idx));catalogBox.addView(row,new LinearLayout.LayoutParams(-1,-2));}shown=end;if(shown<chapters.size()){Button more=btn("加载更多章节（剩余 "+(chapters.size()-shown)+"）");more.setOnClickListener(v->{catalogBox.removeView(v);showMore();});catalogBox.addView(more,new LinearLayout.LayoutParams(-1,dp(52)));}}
 private void openChapter(int idx){if(idx<0||idx>=chapters.size())return;Intent i=new Intent(this,ReaderActivity.class);i.putExtra("title",book.title);i.putExtra("catalog_key",catalogKey);i.putExtra("chapter_index",idx);i.putExtra("source_json",book.sourceJson);startActivity(i);}private void addShelf(){try{String key="book_"+Integer.toHexString(book.title.hashCode());getSharedPreferences("native_shelf",MODE_PRIVATE).edit().putString(key,new JSONObject().put("title",book.title).put("author",book.author).put("intro",book.intro).put("cover",book.coverUrl).put("book_url",book.bookUrl).put("source_name",book.sourceName).put("source_url",book.sourceUrl).put("source_json",book.sourceJson).toString()).apply();LinkedHashSet<String> set=new LinkedHashSet<>(getSharedPreferences("native_shelf",MODE_PRIVATE).getStringSet("keys",Collections.emptySet()));set.add(key);getSharedPreferences("native_shelf",MODE_PRIVATE).edit().putStringSet("keys",set).apply();Toast.makeText(this,"已加入书架",Toast.LENGTH_SHORT).show();}catch(Throwable e){Toast.makeText(this,"加入书架失败",Toast.LENGTH_SHORT).show();}}
 private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(16),dp(16),dp(16),dp(16));GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(18));c.setBackground(g);return c;}private Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextSize(14);b.setAllCaps(false);b.setTextColor(green);return b;}private TextView tx(String s,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setTypeface(Typeface.create("sans",bold?Typeface.BOLD:Typeface.NORMAL));return v;}private LinearLayout.LayoutParams mp(int l,int t,int r,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(dp(l),dp(t),dp(r),dp(b));return p;}private int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
}
